'use client';

import { useStore } from '../../app/stores/useStore';

const ThemeSwitcher = () => {
  const { theme, setTheme } = useStore();

  const themes = [
    { key: 'current', label: 'Current', color: '#FC7000' },
    { key: 'light', label: 'Light', color: '#ffffff' },
    { key: 'dark', label: 'Dark', color: '#0a0a0a' },
  ];

  return (
    <div style={{
      position: 'fixed',
      top: '120px',
      right: '20px',
      zIndex: 1001,
      display: 'flex',
      gap: '10px',
      background: 'rgba(0,0,0,0.8)',
      padding: '10px',
      borderRadius: '8px',
      backdropFilter: 'blur(10px)',
    }}>
      {themes.map((t) => (
        <button
          key={t.key}
          onClick={() => setTheme(t.key)}
          style={{
            background: theme === t.key ? t.color : 'transparent',
            border: `2px solid ${t.color}`,
            color: theme === t.key ? (t.key === 'dark' ? '#ffffff' : '#000000') : t.color,
            padding: '8px 12px',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '12px',
            fontWeight: 'bold',
            transition: 'all 0.3s ease',
          }}
        >
          {t.label}
        </button>
      ))}
    </div>
  );
};

export default ThemeSwitcher;
